                if (size > 200) {
                    context.report(ISSUE, element, context.getLocation(element),
                        "Large vector icons (>" + 200 + "dp) are not fully supported for vector raster generation on older devices");
                }
            } catch (NumberFormatException ignored) {
            }
        }
    }
}
